package com.xuyux.web;

import com.xuyux.util.Base64ToMultipartFileConverter;
import jakarta.annotation.Resource;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;

@RestController
public class TestApi {

    @Resource
    ProviderFeignClient providerFeignClient;

    @GetMapping("/hello")
    public String hello() {
        return providerFeignClient.hello();
    }

    @GetMapping("/uploadBase64Img")
    public String uploadBase64Img() {
        String base64Data = "data:image/jpeg;base64,";
        MultipartFile multipartFile = Base64ToMultipartFileConverter.convert(base64Data);
        return providerFeignClient.testUploadBase64Img(multipartFile);
    }

}
